.version 7.0
.target sm_80
.address_size 64

.visible .entry depthwise_conv(
    .param .u64   input_ptr,    // fp16 input tensor
    .param .u64   weight_ptr,   // fp16 depthwise weight tensor
    .param .u64   output_ptr,   // fp16 output tensor
    .param .u32   batch,
    .param .u32   channels,
    .param .u32   height,
    .param .u32   width,
    .param .u32   ksize,
    .param .u32   stride,
    .param .u32   padding,
    .param .u32   out_h,
    .param .u32   out_w
)
{
    // -----------------------------------------------------------------
    // Thread/block mapping
    //   blockIdx.x  -> batch index
    //   blockIdx.y  -> channel index
    //   blockIdx.z  -> flattened (out_y, out_x) index
    // -----------------------------------------------------------------
    .reg .u32    b_idx, c_idx, out_idx;
    mov.u32      b_idx, %ctaid.x;
    mov.u32      c_idx, %ctaid.y;
    mov.u32      out_idx, %ctaid.z;

    // -----------------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------------
    .reg .u64    in_ptr, w_ptr, out_ptr;
    .reg .u32    B, C, H, W, K, S, P, OH, OW;
    ld.param.u64 in_ptr,  [input_ptr];
    ld.param.u64 w_ptr,   [weight_ptr];
    ld.param.u64 out_ptr, [output_ptr];
    ld.param.u32 B, [batch];
    ld.param.u32 C, [channels];
    ld.param.u32 H, [height];
    ld.param.u32 W, [width];
    ld.param.u32 K, [ksize];
    ld.param.u32 S, [stride];
    ld.param.u32 P, [padding];
    ld.param.u32 OH, [out_h];
    ld.param.u32 OW, [out_w];

    // -----------------------------------------------------------------
    // Derive output coordinates (signed)
    // -----------------------------------------------------------------
    .reg .s32    out_y, out_x;
    .reg .u32    tmp;
    div.u32      tmp, out_idx, OW;          // out_y = out_idx / out_w
    cvt.s32.u32  out_y, tmp;
    mul.lo.u32   tmp, tmp, OW;              // tmp = out_y * out_w
    sub.u32      tmp, out_idx, tmp;         // out_x = out_idx - tmp
    cvt.s32.u32  out_x, tmp;

    // -----------------------------------------------------------------
    // Origin of the receptive field (signed)
    // -----------------------------------------------------------------
    .reg .s32    in_y_origin, in_x_origin;
    cvt.s32.u32  tmp, S;
    mul.lo.s32  in_y_origin, out_y, tmp;    // out_y * stride
    mul.lo.s32  in_x_origin, out_x, tmp;    // out_x * stride
    cvt.s32.u32  tmp, P;
    sub.s32     in_y_origin, in_y_origin, tmp; // - padding
    sub.s32     in_x_origin, in_x_origin, tmp;

    // -----------------------------------------------------------------
    // Accumulator (float32)
    // -----------------------------------------------------------------
    .reg .f32    acc;
    mov.f32     acc, 0f0;

    // -----------------------------------------------------------------
    // Loops over kernel height (ky) and width (kx)
    // -----------------------------------------------------------------
    .reg .u32    ky, kx;
    .reg .s32    in_y, in_x;
    .reg .pred  p_valid;
    .reg .u32    weight_off_u32, input_off_u32;
    .reg .u64    weight_off, input_off;
    .reg .u16    w_half, i_half;
    .reg .f32    w_f, i_f;

    mov.u32 ky, 0;
ky_loop:
    setp.ge.u32 p_valid, ky, K;          // if ky >= K break
    @p_valid bra kx_end_all;

    mov.u32 kx, 0;
kx_loop:
    setp.ge.u32 p_valid, kx, K;          // if kx >= K break
    @p_valid bra ky_inc;

    // ---------- compute input coordinates ----------
    add.s32 in_y, in_y_origin, ky;       // in_y = origin_y + ky
    add.s32 in_x, in_x_origin, kx;       // in_x = origin_x + kx

    // ---------- boundary check ----------
    setp.lt.s32 p_valid, in_y, 0;
    @p_valid bra kx_inc;                 // out of top/left
    setp.ge.s32 p_valid, in_y, H;
    @p_valid bra kx_inc;                 // out of bottom
    setp.lt.s32 p_valid, in_x, 0;
    @p_valid bra kx_inc;                 // out of left
    setp.ge.s32 p_valid, in_x, W;
    @p_valid bra kx_inc;                 // out of right

