    .reg .u64 tmp64, tmp64b;
    cvt.u64.u32 tmp64, b_idx;            // b
    mul.wide.u32 tmp64, tmp64, C;        // b*C
    cvt.u64.u32 tmp64b, c_idx;           // c
    add.u64 tmp64, tmp64, tmp64b;        // b*C + c
    mul.wide.u32 tmp64, tmp64, H;        // *H
    cvt.u64.s32 tmp64b, in_y;            // in_y
    add.u64 tmp64, tmp64, tmp64b;        // +in_y
    mul.wide.u32 tmp64, tmp64, W;        // *W
    cvt.u64.s32 tmp64b, in_x;            // in_x
    add.u64 input_off, tmp64, tmp64b;    // final index
    shl.b64 input_off, input_off, 1;    // *2 because fp16

    // weight offset = (c * K * K) + (ky * K + kx)
    mul.lo.u32 weight_off_u32, c_idx, K;
    mul.lo.u32 weight_off_u32, weight_off_u32, K; // c*K*K
    mul.lo.u32 tmp, ky, K;
    add.u32 tmp, tmp, kx;                // ky*K + kx
    add.u32 weight_off_u32, weight_off_u32, tmp;
    cvt.u64.u32 weight_off, weight_off_u32;
    shl.b64 weight_off, weight_off, 1;   // *2 because fp16

