    ld.global.u16 w_half, [w_ptr + weight_off];
    ld.global.u16 i_half, [in_ptr + input_off];

    // ---------- convert to fp32 ----------
    cvt.f32.f16 w_f, w_half;
    cvt.f32.f16 i_f, i_half;

    // ---------- MAC ----------
    mad.f32 acc, i_f, w_f, acc;

kx_inc:
    add.u32 kx, kx, 1;
    bra kx_loop;

ky_inc:
    add.u32 ky, ky, 1;
    bra ky_loop;

kx_end_all:
    // -----------------------------------------------------------------
    // Write output
    // -----------------------------------------------------------------
    // output offset = ((b * C + c) * OH + out_y) * OW + out_x
    .reg .u64 out_off, tmp64c;
    cvt.u64.u32 tmp64, b_idx;            // b
    mul.wide.u32 tmp64, tmp64, C;        // b*C
    cvt.u64.u32 tmp64c, c_idx;           // c
    add.u64 tmp64, tmp64, tmp64c;        // b*C + c
    mul.wide.u32 tmp64, tmp64, OH;       // *OH
    cvt.u64.s32 tmp64c, out_y;           // out_y
    add.u64 tmp64, tmp64, tmp64c;        // +out_y
    mul.wide.u32 tmp64, tmp64, OW;       // *OW
    cvt.u64.s32 tmp64c, out_x;           // out_x
    add.u64 out_off, tmp64, tmp64c;      // final index
    shl.b64 out_off, out_off, 1;         // *2 because fp16

    // convert accumulator to fp16 (round to nearest)
    cvt.rn.f16.f32 w_half, acc;
    st.global.u16 [out_ptr + out_off], w_half;

    ret;
}
