        S = self.stride               # set by the user
        P = self.padding              # set by the user

        # Compute output spatial dimensions
        OH = (H + 2 * P - K) // S + 1
        OW = (W + 2 * P - K) // S + 1

        # Allocate output tensor
        out = torch.empty((B, C, OH, OW), dtype=torch.float16, device=x.device)

        # Depthwise weight tensor: (C, K, K)
        weight = torch.empty((C, K, K), dtype=torch.float16, device=x.device)

        # Prepare launch configuration
        grid = (B, C, OH * OW)          # (batch, channel, flattened output spatial)
        block = (1, 1, 1)

        # Build argument list (PTX expects pointers and scalars)
        args = [
            x.data_ptr(),               # input_ptr
            weight.data_ptr(),          # weight_ptr
            out.data_ptr(),             # output_ptr
            B, C, H, W, K, S, P, OH, OW
        ]

        # Launch the kernel
        ptx_launch(self.module, "depthwise_conv", grid, block, args)

        return out
